const items = $input.all();

// Extract numeric values for each metric column
const metrics = {};
const metricKeys = Object.keys(items[0].json).filter(k => !isNaN(parseFloat(items[0].json[k])));

for (const key of metricKeys) {
  const values = items.map(item => parseFloat(item.json[key])).filter(v => !isNaN(v));
  if (values.length < 3) continue;

  const mean = values.reduce((a, b) => a + b, 0) / values.length;
  const stdDev = Math.sqrt(values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length);
  const latest = values[values.length - 1];
  const zScore = stdDev > 0 ? (latest - mean) / stdDev : 0;

  metrics[key] = { mean: mean.toFixed(2), stdDev: stdDev.toFixed(2), latest, zScore: zScore.toFixed(2), isAnomaly: Math.abs(zScore) > 2.5 };
}

const anomalies = Object.entries(metrics).filter(([_, v]) => v.isAnomaly).map(([k, v]) => ({ metric: k, ...v }));

return [{
  json: {
    totalMetrics: metricKeys.length,
    anomalyCount: anomalies.length,
    anomalies,
    allMetrics: metrics,
    hasAnomalies: anomalies.length > 0,
    timestamp: new Date().toISOString()
  }
}];

